package net.imadz.codegen.scaffolding.cqrs.template.products

import net.imadz.codegen.scaffolding.cqrs.TypeResolverDSL
import net.imadz.codegen.scaffolding.cqrs.model.products._
import net.imadz.codegen.structure.NamingConventions
import net.imadz.meta.execution._
import net.imadz.meta.products._

object ProductInvocationHostTemplate {
  private def sym(value: String): String = NamingConventions.productSymbol(value)
  private def quote(value: String): String = ujson.write(value)
  private def typeText(ref: net.imadz.codegen.scaffolding.cqrs.TypeRef): String = ref.fqn + (if (ref.typeParams.isEmpty) "" else ref.typeParams.map(typeText).mkString("[", ", ", "]"))
  private def tpe(t: NominalType, m: ProductApplicationModel): String = typeText(TypeResolverDSL.productType(t, m.domain.packages))
  private def field(r: QualifiedReference, m: ProductApplicationModel): ReferenceDeclaration = m.domain.layout.declarations.find(_.ref == r).get
  private def textual(v: String, t: NominalType, m: ProductApplicationModel): String = t match { case NominalType.Named(r) => textual(v + ".value", field(r, m).valueType.get, m); case _ => v }

  def generate(model: ProductApplicationModel): Vector[ProductSourceModel] = model.hosts.map { row =>
    if (row.contract.entry.startOwner.kind == "pipeline") ProductPipelineInvocationHostTemplate.generate(model, row)
    else {
    val h = row.contract; val runtime = row.runtime; val pkg = model.domain.packages(h.saga.ref.context)
    val stem = NamingConventions.strictSymbol(h.id); val name = stem + "Host"
    val originalType = tpe(h.entry.inputType, model); val argsType = tpe(h.argsType, model)
    val trigger = runtime.triggers.find(_.declaration.id == h.entry.triggerId).get.declaration
    def originalArg(slot: String): String = trigger.args.find(_.slot == slot).get.source match {
      case SagaValueSource.SourceField(name) => "original." + sym(name)
      case _ => throw new IllegalArgumentException("original retained trigger source required")
    }
    def resultValue(p: HostParameter): String = p.input match {
      case SagaValueSource.TransactionId => field(p.parameter, model).valueType.get match {
        case n: NominalType.Named => tpe(n, model) + "(identity.transactionId)"
        case _ => "identity.transactionId"
      }
      case SagaValueSource.Args(slot) => originalArg(slot)
      case _ => throw new IllegalArgumentException("explicit result receipt adapter required")
    }
    val originalId = h.entry.inputType.asInstanceOf[NominalType.Named].ref.id
    val readOriginal = pkg + ".infrastructure.serialization.DomainConverters.decode" + originalId + "PB(" + pkg + ".infrastructure.proto." + originalId + "PB.parseFrom(state.original.toByteArray))"
    val identityField = h.association.inputKeys.find(_.id == trigger.idempotency.sourceSlot).get
    val operation = "operationIdentity(original)"
    var text = "package " + pkg + ".application\n\nimport akka.actor.typed.{ActorRef, Behavior}\nimport akka.actor.typed.scaladsl.Behaviors\nimport akka.persistence.typed.PersistenceId\nimport akka.persistence.typed.scaladsl.{Effect, EventSourcedBehavior}\nimport com.google.protobuf.ByteString\nimport net.imadz.infra.saga.strict._\nimport scala.concurrent.{ExecutionContext, Future}\n\nobject " + name + " {\n"
    val identityParts = Vector(quote("truthsrc-finite-host-association-v1"), quote(h.saga.ref.context), quote(h.saga.ref.id), quote(h.saga.version), quote(h.association.id), quote(h.association.version)) ++ h.association.inputKeys.map(r => textual("original." + sym(r.id), field(r, model).valueType.get, model))
    val entryFields = field(h.entry.inputType.asInstanceOf[NominalType.Named].ref, model).valueType.get.asInstanceOf[NominalType.Record].members
    val entrySource = pkg + ".domain." + sym(h.entry.source.owner.head) + "Protocol." + sym(h.entry.source.id)
    text += "  def fromEntry(input: " + entrySource + "): " + originalType + " = " + originalType + entryFields.map(r => "input." + sym(r.id)).mkString("(", ", ", ")") + "\n  final case class ReceiveEntry(input: " + entrySource + ", replyTo: ActorRef[Reply]) extends Request\n"
    text += "  private def operationIdentity(original: " + originalType + "): String = {\n    val buffer = new java.io.ByteArrayOutputStream\n    val out = new java.io.DataOutputStream(buffer)\n    val parts = Vector(" + identityParts.mkString(", ") + ")\n    parts.foreach { part => require(part != null && part.nonEmpty, \"original association key required\"); val bytes = part.getBytes(java.nio.charset.StandardCharsets.UTF_8); out.writeInt(bytes.length); out.write(bytes) }\n    out.flush()\n    \"sha256:\" + java.security.MessageDigest.getInstance(\"SHA-256\").digest(buffer.toByteArray).iterator.map(b => f\"${b & 0xff}%02x\").mkString\n  }\n"
    text += "  private val terminalResults = Set(\"succeeded\", \"rejected-before-effects\", \"compensated\")\n  def nextResult(current: Option[String], observed: Option[String]): Option[String] = if (current.exists(terminalResults)) None else observed.filterNot(current.contains)\n  def classify(status: StrictState): Option[String] = status.status match {\n    case StrictStatus.Succeeded => Some(\"succeeded\")\n    case StrictStatus.Aborted => Some(if (status.evidence.values.exists { case Evidence.Confirmed(id, _) => id.phase == Phase.Prepare; case _ => false }) \"compensated\" else \"rejected-before-effects\")\n    case StrictStatus.RecoveryRequired => Some(if (status.evidence.values.exists(_.isInstanceOf[Evidence.Uncertain])) \"outcome-unknown\" else \"recovery-required\")\n    case _ => None\n  }\n  def validStatus(state: State, status: StrictState): Boolean = state.operation.nonEmpty && status.argsBytes == state.args && status.identity.exists { identity =>\n    val digest = java.security.MessageDigest.getInstance(\"SHA-256\").digest(state.args.toByteArray).iterator.map(b => f\"${b & 0xff}%02x\").mkString\n    identity.transactionId == state.operation && identity.definitionName == " + quote(runtime.runtimeIdentity.name) + " && identity.definitionVersion == " + runtime.runtimeIdentity.version + " && identity.definitionDigest == " + quote(runtime.definitionDigest) + " && identity.argsCodec == " + stem + "Definition.argsCodec.pin && identity.argsDigest == digest && state.identity.forall(_ == identity) && scala.util.Try(StrictSagaProtoConverters.stateToProto(status)).isSuccess\n  }\n"
    text += "  sealed trait Request\n  final case class Submit(original: " + originalType + ", replyTo: ActorRef[Reply]) extends Request\n  final case class Observe(replyTo: ActorRef[Reply]) extends Request\n  private final case class Observed(reply: StrictSagaCoordinator.Reply, replyTo: ActorRef[Reply]) extends Request\n  private final case class Delivered(kind: String, ok: Boolean, replyTo: ActorRef[Reply]) extends Request\n  sealed trait Reply\n  final case class Accepted(identity: TransactionIdentity) extends Reply\n  final case class Waiting(reason: String) extends Reply\n  final case class Conflict(reason: String) extends Reply\n  final case class ResultRecorded(kind: String) extends Reply\n  sealed trait Event\n  final case class Associated(original: ByteString, args: ByteString, operation: String) extends Event\n  final case class IdentityObserved(identity: TransactionIdentity) extends Event\n  final case class ResultIntent(kind: String) extends Event\n  final case class DeliveryAcknowledged(kind: String) extends Event\n  final case class State(original: ByteString = ByteString.EMPTY, args: ByteString = ByteString.EMPTY, operation: String = \"\", identity: Option[TransactionIdentity] = None, result: Option[String] = None, delivered: Boolean = false)\n  trait Delivery {\n"
    h.results.foreach { r => text += "    def " + NamingConventions.strictSymbol(r.kind.wire) + "(destination: " + tpe(field(r.destination.resourceInput, model).valueType.get, model) + ", event: " + pkg + ".domain." + sym(r.event.owner.head) + "Protocol." + sym(r.event.id) + ", identity: TransactionIdentity): Future[Boolean]\n" }
    text += "  }\n  def apply(persistenceId: String, coordinator: ActorRef[StrictSagaCoordinator.Command], delivery: Delivery): Behavior[Request] = Behaviors.setup { context =>\n    require(persistenceId != null && persistenceId.nonEmpty && coordinator != null && delivery != null, \"explicit owned host identity, coordinator and delivery implementations required\")\n    implicit val ec: ExecutionContext = context.executionContext\n    def observe(state: State, replyTo: ActorRef[Reply]): Unit = {\n      val adapter = context.spawnAnonymous(Behaviors.receiveMessage[StrictSagaCoordinator.Reply] { reply => context.self ! Observed(reply, replyTo); Behaviors.stopped })\n      state.identity match { case Some(identity) => coordinator ! StrictSagaCoordinator.Attach(identity, adapter); case None => coordinator ! StrictSagaCoordinator.Start(state.operation, state.args, adapter) }\n    }\n    def deliver(state: State, kind: String, replyTo: ActorRef[Reply]): Unit = {\n      val original = " + readOriginal + "\n      val identity = state.identity.get\n      val result: Future[Boolean] = kind match {\n"
    h.results.foreach { r => text += "        case " + quote(r.kind.wire) + " => delivery." + NamingConventions.strictSymbol(r.kind.wire) + "(original." + sym(r.destination.resourceInput.id) + ", " + pkg + ".domain." + sym(r.event.owner.head) + "Protocol." + sym(r.event.id) + r.inputs.map(resultValue).mkString("(", ", ", ")") + ", identity)\n" }
    text += "        case _ => Future.failed(new IllegalArgumentException(\"unmapped result kind\"))\n      }\n      context.pipeToSelf(result)(value => Delivered(kind, value.getOrElse(false), replyTo))\n    }\n    EventSourcedBehavior[Request, Event, State](PersistenceId.ofUniqueId(persistenceId), State(), (state, request) => request match {\n      case ReceiveEntry(input, replyTo) => context.self ! Submit(fromEntry(input), replyTo); Effect.none\n      case Submit(original, replyTo) =>\n        val originalBytes = " + pkg + ".infrastructure.serialization.DomainConverters.encode" + originalId + "PB(original).toByteString\n        val args: " + argsType + " = " + argsType + runtime.args.slots.map(a => originalArg(a.slot)).mkString("(", ", ", ")") + "\n        val argsBytes = " + stem + "Definition.argsCodec.encode(args)\n        val operation = " + operation + "\n        if (state.operation.nonEmpty && (state.operation != operation || state.original != originalBytes || state.args != argsBytes)) Effect.none.thenRun((_: State) => replyTo ! Conflict(\"different original input under existing host\"))\n        else if (state.operation.nonEmpty) Effect.none.thenRun((s: State) => observe(s, replyTo))\n        else Effect.persist(Associated(originalBytes, argsBytes, operation)).thenRun((s: State) => observe(s, replyTo))\n      case Observe(replyTo) => if (state.operation.isEmpty) Effect.none.thenRun((_: State) => replyTo ! Waiting(\"not associated\")) else Effect.none.thenRun((s: State) => observe(s, replyTo))\n      case Observed(StrictSagaCoordinator.Status(status), replyTo) => status.identity match {\n        case None => Effect.none.thenRun((_: State) => replyTo ! Waiting(\"identity not yet observed\"))\n        case Some(identity) if !validStatus(state, status) => Effect.none.thenRun((_: State) => replyTo ! Conflict(\"authoritative identity conflict\"))\n        case Some(identity) =>\n          val result = classify(status)\n          val events = (if (state.identity.isEmpty) Vector[Event](IdentityObserved(identity)) else Vector.empty) ++ nextResult(state.result, result).map(k => ResultIntent(k)).toVector\n          Effect.persist(events).thenRun { s: State => s.result match { case Some(kind) if !s.delivered => deliver(s, kind, replyTo); case Some(kind) => replyTo ! ResultRecorded(kind); case None => replyTo ! Accepted(identity) } }\n      }\n      case Observed(StrictSagaCoordinator.Denied(reason), replyTo) => Effect.none.thenRun((_: State) => replyTo ! Waiting(reason))\n      case Observed(StrictSagaCoordinator.ConflictingIdentity, replyTo) => Effect.none.thenRun((_: State) => replyTo ! Conflict(\"coordinator identity conflict\"))\n      case Delivered(kind, true, replyTo) if state.result.contains(kind) => Effect.persist(DeliveryAcknowledged(kind)).thenRun((_: State) => replyTo ! ResultRecorded(kind))\n      case Delivered(_, _, replyTo) => Effect.none.thenRun((_: State) => replyTo ! Waiting(\"delivery unacknowledged\"))\n    }, (state, event) => event match {\n      case Associated(original, args, operation) => state.copy(original = original, args = args, operation = operation)\n      case IdentityObserved(identity) => state.copy(identity = Some(identity))\n      case ResultIntent(kind) => state.copy(result = Some(kind), delivered = false)\n      case DeliveryAcknowledged(_) => state.copy(delivered = true)\n    })\n  }\n}\n"
    text = ProductHostIOTemplate.wire(text, stem, readOriginal, "Waiting", ProductHostIOTemplate.resourcePolicy(h).isDefined,
      ProductHostIOTemplate.occurrenceBridge(h).map { case (gate, _) =>
        val envelope = tpe(model.ports.find(port => port.ref == gate.port.ref && port.version == gate.port.version).get.inputType, model)
        (envelope, originalType)
      })
    ProductSourceModel(NamingConventions.productPackagePath(pkg, "application/" + stem + "Host.scala"), "// @generated by CodegenMain:semantic-products-application-1\n" + text, "invocation-host", Vector(h.source), model.footprint)
    }
  }
}
